def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    sources = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 2 and all(
                grid[rr][cc] == 3
                for rr in range(r - 1, r + 2)
                for cc in range(c - 1, c + 2)
                if (rr, cc) != (r, c)
            ):
                sources.append((r, c))
    source_set = set(sources)
    for r, c in sources:
        horiz_walls = sum(grid[r][x] == 2 for x in range(w))
        vert_walls = sum(grid[y][c] == 2 for y in range(h))
        dr, dc = (0, 1) if vert_walls > horiz_walls else (1, 0)
        for sign in (-1, 1):
            y, x = r + dr * 2 * sign, c + dc * 2 * sign
            while 0 <= y < h and 0 <= x < w:
                if grid[y][x] == 2:
                    if (y, x) not in source_set:
                        for oy in (-1, 0, 1):
                            for ox in (-1, 0, 1):
                                yy, xx = y + oy, x + ox
                                if (oy, ox) != (0, 0) and 0 <= yy < h and 0 <= xx < w:
                                    out[yy][xx] = 1
                elif grid[y][x] == 0:
                    out[y][x] = 1
                y += dr * sign
                x += dc * sign
    return out
